-- Safety checks: FY2025 and all referenced accounts/subaccounts must already exist.
do $$
declare
  v_fy_count integer;
begin
  select count(*) into v_fy_count
  from accounting.fiscal_years f
  join accounting.companies c on c.id=f.company_id
  where c.name='akmic合同会社'
    and f.name='2025年度'
    and f.start_date=date '2025-11-01'
    and f.end_date=date '2026-10-31';

  if v_fy_count <> 1 then
    raise exception 'Expected exactly one FY2025 fiscal year, got %', v_fy_count;
  end if;
end
$$;

