c as (
  select id
  from accounting.companies
  where name='akmic合同会社'
  order by created_at
  limit 1
),
fy as (
  select f.id
  from accounting.fiscal_years f
  join c on c.id=f.company_id
  where f.name='2025年度'
    and f.start_date=date '2025-11-01'
    and f.end_date=date '2026-10-31'
  limit 1
)
insert into accounting.journals (
  company_id,
  fiscal_year_id,
  entry_date,
  voucher_no,
  description,
  memo,
  status,
  total_debit,
  total_credit,
  source_system,
  source_record_id,
  source_data,
  entry_kind
)
select
  c.id,
  fy.id,
  src.entry_date::date,
  src.voucher_no,
  src.description,
  src.memo,
  'draft',
  0,
  0,
  'moneyforward',
  src.source_record_id,
  src.source_data,
  src.entry_kind
from src
cross join c
cross join fy
where not exists (
  select 1
  from accounting.journals j
  where j.company_id=c.id
    and j.source_system='moneyforward'
    and j.source_record_id=src.source_record_id
);

