('EW%2FoUpLrSHE4aYLRcA%2FGIG%2FwyG2TyD0ngyoXmyxhihg%3D',1,'credit','b8fAk3xeYsBmHNXczmO3ig%3D%3D','eOCEMUAA%2FLJUda99tgjCSQ%3D%3D',8000,'倉林スポーツ整体院',null,null,null)
),
c as (
  select id
  from accounting.companies
  where name='akmic合同会社'
  order by created_at
  limit 1
),
resolved as (
  select
    j.id as journal_id,
    src.line_no,
    src.side,
    a.id as account_id,
    sa.id as sub_account_id,
    src.amount::numeric as amount,
    src.memo,
    src.department,
    src.tax_name,
    src.partner_name,
    src.account_source_record_id,
    src.sub_account_source_record_id
  from src
  cross join c
  join accounting.journals j
    on j.company_id=c.id
   and j.source_system='moneyforward'
   and j.source_record_id=src.journal_source_record_id
  left join accounting.accounts a
    on a.company_id=c.id
   and a.source_system='moneyforward'
   and a.source_record_id=src.account_source_record_id
  left join accounting.sub_accounts sa
    on sa.company_id=c.id
   and sa.account_id=a.id
   and sa.source_system='moneyforward'
   and sa.source_record_id=src.sub_account_source_record_id
)
insert into accounting.journal_lines (
  journal_id,
  line_no,
  account_id,
  sub_account_id,
  side,
  amount,
  memo,
  department,
  tax_name,
  partner_name
)
select
  journal_id,
  line_no,
  account_id,
  sub_account_id,
  side,
  amount,
  memo,
  department,
  tax_name,
  partner_name
from resolved
where account_id is not null
  and (sub_account_source_record_id is null or sub_account_id is not null)
on conflict (journal_id, line_no, side) do nothing;

-- Fail fast if any line could not resolve its account or sub-account.
do $$
declare
  v_line_count integer;
begin
  select count(*) into v_line_count
  from accounting.journal_lines jl
  join accounting.journals j on j.id=jl.journal_id
  join accounting.fiscal_years f on f.id=j.fiscal_year_id
  where j.source_system='moneyforward'
    and f.name='2025年度';

  if v_line_count <> 817 then
    raise exception 'Expected 817 FY2025 journal lines, got %. Missing account/sub-account mapping is likely.', v_line_count;
  end if;
end
$$;

-- Posting trigger recalculates totals from journal_lines and validates balance.
update accounting.journals j
set status='posted'
from accounting.fiscal_years f
where j.fiscal_year_id=f.id
  and f.name='2025年度'
  and j.source_system='moneyforward'
  and j.status='draft';

-- Direct evidence link using Money Forward voucher_file_ids -> CloudBox file ID.
insert into accounting.journal_receipts (
  journal_id,
  receipt_id,
  relation_type
)
select
  j.id,
  r.id,
  'evidence'
from accounting.journals j
join accounting.fiscal_years f
  on f.id=j.fiscal_year_id
cross join lateral jsonb_array_elements_text(
  coalesce(j.source_data->'voucher_file_ids','[]'::jsonb)
) v(file_id)
join accounting.receipts r
  on r.company_id=j.company_id
 and r.source_system='moneyforward_cloudbox'
 and r.source_record_id=v.file_id
where f.name='2025年度'
  and j.source_system='moneyforward'
on conflict (journal_id, receipt_id) do nothing;

-- Final validation.
do $$
declare
  v_journals integer;
  v_posted integer;
  v_lines integer;
  v_debit numeric;
  v_credit numeric;
  v_links integer;
  v_distinct_receipts integer;
  v_expected_vouchers integer;
begin
  select
    count(*),
    count(*) filter (where j.status='posted')
  into v_journals, v_posted
  from accounting.journals j
  join accounting.fiscal_years f on f.id=j.fiscal_year_id
  where j.source_system='moneyforward'
    and f.name='2025年度';

  select
    count(*),
    coalesce(sum(jl.amount) filter (where jl.side='debit'),0),
    coalesce(sum(jl.amount) filter (where jl.side='credit'),0)
  into v_lines, v_debit, v_credit
  from accounting.journal_lines jl
  join accounting.journals j on j.id=jl.journal_id
  join accounting.fiscal_years f on f.id=j.fiscal_year_id
  where j.source_system='moneyforward'
    and f.name='2025年度';

  select
    count(*),
    count(distinct jr.receipt_id)
  into v_links, v_distinct_receipts
  from accounting.journal_receipts jr
  join accounting.journals j on j.id=jr.journal_id
  join accounting.fiscal_years f on f.id=j.fiscal_year_id
  where j.source_system='moneyforward'
    and f.name='2025年度';

  select coalesce(sum(jsonb_array_length(coalesce(j.source_data->'voucher_file_ids','[]'::jsonb))),0)
  into v_expected_vouchers
  from accounting.journals j
  join accounting.fiscal_years f on f.id=j.fiscal_year_id
  where j.source_system='moneyforward'
    and f.name='2025年度';

  if v_journals <> 403 then
    raise exception 'Expected 403 FY2025 journals, got %', v_journals;
  end if;
  if v_posted <> 403 then
    raise exception 'Expected 403 posted FY2025 journals, got %', v_posted;
  end if;
  if v_lines <> 817 then
    raise exception 'Expected 817 FY2025 journal lines, got %', v_lines;
  end if;
  if v_debit <> 28990831 or v_credit <> 28990831 then
    raise exception 'Unexpected FY2025 totals debit %, credit %', v_debit, v_credit;
  end if;
  if v_expected_vouchers <> 218 then
    raise exception 'Expected 218 voucher_file_ids, got %', v_expected_vouchers;
  end if;
  if v_links <> 218 or v_distinct_receipts <> 218 then
    raise exception 'Expected 218 direct journal-receipt links and 218 distinct receipts, got links %, receipts %',
      v_links, v_distinct_receipts;
  end if;
end
$$;

commit;
